$().ready(function(){$('a[rel="external"]').click(function(){window.open($(this).attr("href"));return false});$("#container form fieldset legend:first-child").each(function(){$(this).siblings().wrapAll("<div>")});$("#container form fieldset:gt(0)").addClass("closed");$("#container form fieldset legend").click(function(){$(this).parent().toggleClass("closed",100);return false});$("#container #install-user #name_first").change(function(){var b=$("#container #install-user #name_first").val();var a=$("#container #install-user #name_last").val();var c=b+a;$("#container #install-user #username").val(c.toLowerCase())});$("#container #install-user #name_last").change(function(){var b=$("#container #install-user #name_first").val();var a=$("#container #install-user #name_last").val();var c=b+a;$("#container #install-user #username").val(c.toLowerCase())})});